    let id = 0;
    const pending = new Map();
    ws.on("message", (raw) => {
      const msg = JSON.parse(raw.toString());
      const entry = pending.get(msg.id);
      if (!entry) return;
      pending.delete(msg.id);
      if (msg.error) entry.reject(new Error(JSON.stringify(msg.error)));
      else entry.resolve(msg.result);
    });
    ws.on("error", reject);
    ws.on("open", () => {
      const send = (method, params = {}) =>
        new Promise((res, rej) => {
          const nextId = ++id;
          pending.set(nextId, { resolve: res, reject: rej });
          ws.send(JSON.stringify({ id: nextId, method, params }));
        });

      const evaluate = async (expression) => {
        const result = await send("Runtime.evaluate", {
          expression: `(() => { ${expression.includes("return") ? expression : `return (${expression});`} })()`,
          awaitPromise: true,
          returnByValue: true,
        });
        if (result.exceptionDetails)
          throw new Error(
            `evaluate failed: ${result.exceptionDetails.exception?.description ?? result.exceptionDetails.text}\n${expression}`,
          );
        return result.result.value;
      };

      const waitFor = async (expression, { timeout = 5000, label } = {}) => {
        const deadline = Date.now() + timeout;
        for (;;) {
          if ((await evaluate(expression)) === true) return;
          if (Date.now() > deadline)
            throw new Error(`timeout waiting for ${label ?? expression}`);
          await new Promise((r) => setTimeout(r, 25));
        }
      };

      const key = async (opts) => {
        for (const type of ["keyDown", "keyUp"]) {
          await send("Input.dispatchKeyEvent", { type, ...opts });
        }
      };

      const screenshot = async () => (await send("Page.captureScreenshot", {})).data;

      resolve({
        evaluate,
        waitFor,
        key,
        screenshot,
        reloadPlugin: () =>
          evaluate(
            `return app.plugins.disablePlugin(${JSON.stringify(PLUGIN_ID)}).then(() => app.plugins.enablePlugin(${JSON.stringify(PLUGIN_ID)})).then(() => true);`,
          ),
        close: () => ws.close(),
      });
    });
  });
