  const nodes = app.plugins.plugins["@discourse-graph/obsidian"].settings.nodeTypes;
  const files = app.vault.getMarkdownFiles().filter((f) => f.path !== ${json(SCRATCH)});
  const match = files.find((f) => nodes.some((n) => f.basename.startsWith(n.format.replace("{content}", "").trim())));
