      else await app.vault.create(${json(SCRATCH)}, ${json(body)});
      const file = app.vault.getAbstractFileByPath(${json(SCRATCH)});
      app.workspace.detachLeavesOfType("markdown");
      const leaf = app.workspace.getLeaf(true);
      await leaf.openFile(file, { state: { mode: "source" } });
      app.workspace.setActiveLeaf(leaf, { focus: true });
      const view = app.workspace.getActiveViewOfType(obsidian_MarkdownView_placeholder);
      return true;
    })();
  `.replace("obsidian_MarkdownView_placeholder", "app.workspace.activeLeaf.view.constructor"));
