  check(
    `${label}: focus returned to the editor`,
    focus.hasFocus === true,
    JSON.stringify(focus),
  );
  check(
    `${label}: cursor sits after the inserted link`,
    focus.cursor.line === 0 && focus.cursor.ch > 6,
    `ch=${focus.cursor.ch}`,
  );
  check(
    `${label}: inserted into the pre-open note`,
    focus.path === SCRATCH,
    focus.path,
  );
  console.log(`   chosen row: ${chosen}`);
};

await runInsertScenario({
  label: "wikilink/shortest",
  useMarkdownLinks: false,
  newLinkFormat: "shortest",
});
await runInsertScenario({
  label: "markdown/absolute",
  useMarkdownLinks: true,
  newLinkFormat: "absolute",
});

// ---------------------------------------------------------------- scenario 2
// Selection is replaced rather than orphaned.
await client.evaluate(`
  app.vault.setConfig("useMarkdownLinks", false);
  app.vault.setConfig("newLinkFormat", "shortest");
  return true;
`);
await openScratchAt("replace THIS please\n", 0, 0);
await client.evaluate(`
  const editor = app.workspace.activeLeaf.view.editor;
  editor.setSelection({ line: 0, ch: 8 }, { line: 0, ch: 12 });
  return true;
`);
await openSearch();
await typeQuery(firstNodeTitle.slice(0, 4));
await pressModEnter();
await client.waitFor(`!document.querySelector(".dg-node-search-modal")`, {
  label: "modal closed (selection case)",
});
const selectionText = await readScratch();
check(
  "selection is replaced by the link",
  selectionText.startsWith("replace ") &&
    selectionText.endsWith(" please\n") &&
    !selectionText.includes("THIS"),
  JSON.stringify(selectionText),
);

// ---------------------------------------------------------------- scenario 3
// Reading mode has no cursor: the action must be absent.
await openScratchAt("reading mode\n", 0, 0);
await client.evaluate(`
  return app.workspace.activeLeaf.setViewState({
    type: "markdown",
    state: { file: ${json(SCRATCH)}, mode: "preview" },
  }).then(() => true);
