await client.waitFor(`app.workspace.activeLeaf.view.getMode() === "preview"`, {
  label: "reading mode active",
});
await openSearch();
const readingLabels = await footerLabels();
check(
  "insert action absent in reading mode",
  !readingLabels.some((l) => l.includes("insert link at cursor")),
  readingLabels.join(" / "),
);
await closeModalIfOpen();
await client.waitFor(`!document.querySelector(".dg-node-search-modal")`, {
  label: "modal closed (reading mode)",
});

// ---------------------------------------------------------------- scenario 4
// No markdown view at all: the action must be absent.
await client.evaluate(`
  app.workspace.detachLeavesOfType("markdown");
  return true;
`);
await openSearch();
const emptyLabels = await footerLabels();
check(
  "insert action absent with no note open",
  !emptyLabels.some((l) => l.includes("insert link at cursor")),
  emptyLabels.join(" / "),
);
await closeModalIfOpen();

// ---------------------------------------------------------------- teardown
await client.evaluate(`
  app.vault.setConfig("useMarkdownLinks", ${json(savedConfig.useMarkdownLinks)});
  app.vault.setConfig("newLinkFormat", ${json(savedConfig.newLinkFormat)});
  const scratch = app.vault.getAbstractFileByPath(${json(SCRATCH)});
  return (scratch ? app.vault.trash(scratch, true) : Promise.resolve()).then(() => true);
`);
console.log("restored vault link config, trashed scratch note");

const failed = results.filter((r) => !r.pass);
console.log(`\n${results.length - failed.length}/${results.length} assertions passed`);
client.close();
process.exit(failed.length ? 1 : 0);
