// Artifact capture for the CDP verification run. Off unless CAPTURE=1, so
// ordinary verification stays fast.
//
// The driver acts at machine speed, so a raw recording has nothing to watch
// between states. Scenarios therefore call `beat("what just happened")` at each
// semantic step: the run pauses, which holds the preceding frame on screen, and
// the beat's text is burned in as a caption over exactly that held stretch.
import { execFile } from "node:child_process";
import { mkdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { promisify } from "node:util";

const run = promisify(execFile);

export const CAPTURE_ENABLED = process.env.CAPTURE === "1";
export const ARTIFACT_DIR =
  process.env.ARTIFACT_DIR ?? path.join(process.cwd(), "artifacts");
/** Per-character delay while typing, so the query is readable as it forms. */
export const TYPE_DELAY_MS = CAPTURE_ENABLED ? 90 : 0;

const DWELL_MS = 1600; // how long each beat holds its frame
const MIN_FRAME_MS = 40; // the concat demuxer ignores shorter durations
const TAIL_FRAME_MS = 2000; // hold the final state before the gif loops
const FONT = "/System/Library/Fonts/Supplemental/Arial.ttf";

export const prepareArtifactDir = async () => {
  if (!CAPTURE_ENABLED) return;
  await rm(ARTIFACT_DIR, { recursive: true, force: true });
  await mkdir(ARTIFACT_DIR, { recursive: true });
};

export const saveStill = async ({ client, name, clipSelector }) => {
  if (!CAPTURE_ENABLED) return null;
  const clip = clipSelector
    ? await client.evaluate(`
        const el = document.querySelector(${JSON.stringify(clipSelector)});
        if (!el) return null;
        const r = el.getBoundingClientRect();
        return { x: r.x, y: r.y, width: r.width, height: r.height, scale: 1 };
      `)
    : null;
  const data = await client.screenshot(clip ? { clip } : {});
  const file = path.join(ARTIFACT_DIR, `${name}.png`);
  await writeFile(file, Buffer.from(data, "base64"));
  return file;
};

export const recorded = async ({ client, name, body }) => {
  if (!CAPTURE_ENABLED) {
    // Beats still run, minus the pause, so the two modes exercise one code path.
    return body({ beat: async () => {} });
  }

  const frameDir = path.join(ARTIFACT_DIR, `.frames-${name}`);
  await mkdir(frameDir, { recursive: true });
  const frames = [];
  const beats = [];

  await client.startScreencast(({ data, timestamp }) => {
    const file = path.join(frameDir, `f${String(frames.length).padStart(4, "0")}.png`);
    frames.push({ file, timestamp });
    // Fire-and-forget: awaiting here would stall the ack and drop frames.
    void writeFile(file, Buffer.from(data, "base64"));
  });

  // The pause holds whatever is on screen now, so the caption belongs to the
  // frame already captured — not to the next one, which arrives after the dwell.
  const beat = async (text) => {
    beats.push({ text, frameIndex: Math.max(0, frames.length - 1) });
    console.log(`   · ${text}`);
    await new Promise((r) => setTimeout(r, DWELL_MS));
  };

  try {
    return await body({ beat });
  } finally {
    await new Promise((r) => setTimeout(r, 400));
    await client.stopScreencast();
    await encode({ frames, beats, frameDir, name });
    await rm(frameDir, { recursive: true, force: true });
  }
};

/** Cumulative output-timeline start time of every frame, in seconds. */
const buildTimeline = (frames) => {
  const durations = frames.map((frame, index) => {
    const next = frames[index + 1];
    const ms = next
      ? Math.max(MIN_FRAME_MS, (next.timestamp - frame.timestamp) * 1000)
      : TAIL_FRAME_MS;
    return ms / 1000;
  });
  const starts = [];
  let clock = 0;
  for (const duration of durations) {
    starts.push(clock);
    clock += duration;
  }
  return { durations, starts, total: clock };
};

const captionFilters = async ({ beats, frames, timeline, frameDir }) => {
  const filters = [];
  for (const [index, mark] of beats.entries()) {
    const next = beats[index + 1];
    const from = timeline.starts[mark.frameIndex] ?? 0;
    const to = next
      ? (timeline.starts[next.frameIndex] ?? timeline.total)
      : timeline.total;
    if (to - from < 0.2) continue;

    // A textfile avoids escaping colons, commas and quotes inside drawtext.
    const textFile = path.join(frameDir, `caption-${index}.txt`);
    await writeFile(textFile, `${index + 1}. ${mark.text}`);
    filters.push(
      [
        `drawtext=fontfile=${FONT}`,
        `textfile=${textFile}`,
        "fontcolor=white",
        "fontsize=26",
        "box=1",
        "boxcolor=black@0.82",
        "boxborderw=16",
        "x=(w-text_w)/2",
        "y=h-th-28",
        `enable='between(t,${from.toFixed(3)},${to.toFixed(3)})'`,
      ].join(":"),
    );
  }
  return filters;
};

const encode = async ({ frames, beats, frameDir, name }) => {
  if (frames.length < 2) {
    console.log(`   (no recording for ${name}: ${frames.length} frame(s))`);
    return;
  }

  const timeline = buildTimeline(frames);
  const lines = frames.map(
    (frame, index) =>
      `file '${path.basename(frame.file)}'\nduration ${timeline.durations[index].toFixed(3)}`,
  );
  // The concat demuxer drops the last entry's duration unless the file repeats.
  lines.push(`file '${path.basename(frames.at(-1).file)}'`);
  const listFile = path.join(frameDir, "frames.txt");
  await writeFile(listFile, `${lines.join("\n")}\n`);

  const captions = await captionFilters({ beats, frames, timeline, frameDir });
  const base = ["fps=12", "scale=900:-1:flags=lanczos", ...captions].join(",");

  const mp4 = path.join(ARTIFACT_DIR, `${name}.mp4`);
  await run("ffmpeg", [
    "-y", "-loglevel", "error",
    "-f", "concat", "-safe", "0", "-i", listFile,
    // yuv420p with even dimensions is what browsers will actually play.
    "-vf", `${base},pad=ceil(iw/2)*2:ceil(ih/2)*2`,
    "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "26", "-movflags", "+faststart",
    mp4,
  ]);

  const gif = path.join(ARTIFACT_DIR, `${name}.gif`);
  await run("ffmpeg", [
    "-y", "-loglevel", "error",
    "-f", "concat", "-safe", "0", "-i", listFile,
    "-vf",
    `${base},split[a][b];[a]palettegen=max_colors=64[p];[b][p]paletteuse=dither=bayer:bayer_scale=3`,
    "-loop", "0",
    gif,
  ]);

  console.log(
    `   ${name}: ${frames.length} frames, ${timeline.total.toFixed(1)}s, ${beats.length} captions`,
  );
};
EOF
