// Artifact capture: one captioned mp4 per scenario, plus stills. Off unless
// CAPTURE=1, so day-to-day verification stays fast.
//
// The point of the captions: the driver acts at machine speed, so a raw
// recording has nothing watchable between states — the modal opens in one frame,
// the edit lands in the next. Slowing playback does not help. Instead each
// scenario calls `beat("what just happened")`, which grabs a still, holds it,
// and burns the text in over exactly that stretch.
import { execFile } from "node:child_process";
import { mkdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { promisify } from "node:util";

const run = promisify(execFile);

export const CAPTURE_ENABLED = process.env.CAPTURE === "1";
export const ARTIFACT_DIR =
  process.env.ARTIFACT_DIR ?? path.join(process.cwd(), "artifacts");
/** Per-character typing delay, so a query is readable as it forms. */
export const TYPE_DELAY_MS = CAPTURE_ENABLED ? 90 : 0;

/** Gif runs ~40x the size of the mp4 for the same clip, so it is opt-in. */
const WRITE_GIF = process.env.GIF === "1";
const DWELL_MS = 2600;
const MIN_FRAME_MS = 40;
/**
 * Frames arrive only on visual change, so an idle stretch — waiting on a
 * debounced save, say — would otherwise stretch one frame across the whole wait
 * and produce a 90-second clip of a 20-second run.
 */
const MAX_FRAME_MS = 900;
const TAIL_FRAME_MS = 2000;
/** Arial has neither ⌘ nor ↵; Arial Unicode covers both. Quoted for the space. */
const FONT = "'/System/Library/Fonts/Supplemental/Arial Unicode.ttf'";

export const prepareArtifactDir = async () => {
  if (!CAPTURE_ENABLED) return;
  await rm(ARTIFACT_DIR, { recursive: true, force: true });
  await mkdir(ARTIFACT_DIR, { recursive: true });
};

/**
 * Collapses both sidebars for the capture run. Beyond a tighter, smaller frame,
 * this keeps whatever is docked in them — unrelated notes, chat panes — out of
 * artifacts that end up on a public pull request.
 */
export const collapseChrome = async (client) => {
  if (!CAPTURE_ENABLED) return { left: false, right: false };
  const was = await client.evaluate(`return {
    left: !app.workspace.leftSplit.collapsed,
    right: !app.workspace.rightSplit.collapsed,
  };`);
  await client.evaluate(`
    app.workspace.leftSplit.collapse();
    app.workspace.rightSplit.collapse();
    return true;
  `);
  return was;
};

export const restoreChrome = async (client, was) => {
  if (!CAPTURE_ENABLED || !was) return;
  await client.evaluate(`
    ${was.left ? "app.workspace.leftSplit.expand();" : ""}
    ${was.right ? "app.workspace.rightSplit.expand();" : ""}
    return true;
  `);
};

export const saveStill = async ({ client, name, clipSelector }) => {
  if (!CAPTURE_ENABLED) return null;
  const clip = clipSelector ? await client.rectOf(clipSelector) : null;
  const data = await client.screenshot(clip ? { clip } : {});
  const file = path.join(ARTIFACT_DIR, `${name}.png`);
  await writeFile(file, Buffer.from(data, "base64"));
  return file;
};

/**
 * Runs `body({ beat })` while recording. Without CAPTURE=1 the beats are no-ops,
 * so both modes exercise one code path.
 */
export const recorded = async ({ client, name, body }) => {
  if (!CAPTURE_ENABLED) return body({ beat: async () => {} });

  const frameDir = path.join(ARTIFACT_DIR, `.frames-${name}`);
  await mkdir(frameDir, { recursive: true });
  const frames = [];
  const beats = [];

  const framePath = () =>
    path.join(frameDir, `f${String(frames.length).padStart(4, "0")}.png`);

  await client.startScreencast(({ data, timestamp }) => {
    const file = framePath();
    frames.push({ file, timestamp });
    // Fire-and-forget: awaiting here stalls the ack and drops frames.
    void writeFile(file, Buffer.from(data, "base64"));
  });

  /**
   * Each beat appends its own explicitly-timed frame. Deriving caption spans
   * from screencast frame indices instead is unreliable: several beats can land
   * on one index, collapsing their captions to zero width.
   */
  const beat = async (text) => {
    const data = await client.screenshot();
    const file = framePath();
    await writeFile(file, Buffer.from(data, "base64"));
    beats.push({ text, frameIndex: frames.length });
    frames.push({ file, timestamp: null, duration: DWELL_MS });
    console.log(`   · ${text}`);
  };

  try {
    return await body({ beat });
  } finally {
    // Let the closing frames land before tearing the screencast down.
    await new Promise((r) => setTimeout(r, 400));
    await client.stopScreencast();
    await encode({ frames, beats, frameDir, name });
    await rm(frameDir, { recursive: true, force: true });
  }
};

const buildTimeline = (frames) => {
  const durations = frames.map((frame, index) => {
    if (frame.duration) return frame.duration / 1000;
    const next = frames[index + 1];
    if (!next || next.timestamp === null || frame.timestamp === null)
      return TAIL_FRAME_MS / 1000;
    const gap = (next.timestamp - frame.timestamp) * 1000;
    return Math.min(MAX_FRAME_MS, Math.max(MIN_FRAME_MS, gap)) / 1000;
  });
  const starts = [];
  let clock = 0;
  for (const duration of durations) {
    starts.push(clock);
    clock += duration;
  }
  return { durations, starts, total: clock };
};

const captionFilters = async ({ beats, timeline, frameDir }) => {
  const filters = [];
  for (const [index, mark] of beats.entries()) {
    const from = timeline.starts[mark.frameIndex] ?? 0;
    // The closing caption holds to the end, so the final state is never left on
    // screen unexplained while the clip tails out.
    const to =
      index === beats.length - 1
        ? timeline.total
        : from + timeline.durations[mark.frameIndex];
    if (to - from < 0.2) continue;

    // A textfile avoids escaping colons, commas and quotes inside drawtext.
    const textFile = path.join(frameDir, `caption-${index}.txt`);
    await writeFile(textFile, `${index + 1}. ${mark.text}`);
    filters.push(
      [
        `drawtext=fontfile=${FONT}`,
        `textfile=${textFile}`,
        "fontcolor=white",
        "fontsize=26",
        "box=1",
        "boxcolor=black@0.82",
        "boxborderw=16",
        "x=(w-text_w)/2",
        "y=h-th-28",
        `enable='between(t,${from.toFixed(3)},${to.toFixed(3)})'`,
      ].join(":"),
    );
  }
  return filters;
};

const encode = async ({ frames, beats, frameDir, name }) => {
  if (frames.length < 2) {
    console.log(`   (no recording for ${name}: ${frames.length} frame(s))`);
    return;
  }

  const timeline = buildTimeline(frames);
  const lines = frames.map(
    (frame, index) =>
      `file '${path.basename(frame.file)}'\nduration ${timeline.durations[index].toFixed(3)}`,
  );
  // The concat demuxer drops the last entry's duration unless the file repeats.
  lines.push(`file '${path.basename(frames.at(-1).file)}'`);
  const listFile = path.join(frameDir, "frames.txt");
  await writeFile(listFile, `${lines.join("\n")}\n`);

  const captions = await captionFilters({ beats, timeline, frameDir });
  const base = ["fps=12", "scale=900:-1:flags=lanczos", ...captions].join(",");

  const mp4 = path.join(ARTIFACT_DIR, `${name}.mp4`);
  await run("ffmpeg", [
    "-y", "-loglevel", "error",
    "-f", "concat", "-safe", "0", "-i", listFile,
    // yuv420p with even dimensions is what browsers will actually play.
    "-vf", `${base},pad=ceil(iw/2)*2:ceil(ih/2)*2`,
    "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "26",
    "-movflags", "+faststart",
    mp4,
  ]);

  if (WRITE_GIF) {
    const gif = path.join(ARTIFACT_DIR, `${name}.gif`);
    await run("ffmpeg", [
      "-y", "-loglevel", "error",
      "-f", "concat", "-safe", "0", "-i", listFile,
      "-vf",
      `${base},split[a][b];[a]palettegen=max_colors=64[p];[b][p]paletteuse=dither=bayer:bayer_scale=3`,
      "-loop", "0",
      gif,
    ]);
  }

  console.log(
    `   ${name}: ${frames.length} frames, ${timeline.total.toFixed(1)}s, ${beats.length} captions`,
  );
};
